package store

import "fmt"

// Seats is an organization's seat use against its plan's limit.
type Seats struct {
	Used  int
	Limit int // UnlimitedSeats when the plan has no limit
}

// SeatLimitError says a change needs a seat the organization does not have, or would leave it over its limit.
type SeatLimitError struct {
	Limit int
	Used  int
}

func (e *SeatLimitError) Error() string {
	return fmt.Sprintf("seat limit reached: %d of %d seats used", e.Used, e.Limit)
}

// Seats returns an organization's seat use.
func (s *Store) Seats(orgID string) (Seats, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[orgID]
	if !ok {
		return Seats{}, false
	}
	return Seats{Used: s.seatsUsed(orgID), Limit: o.Plan.SeatLimit()}, true
}

// seatsUsed counts members whose role is not viewer, plus invites that are neither accepted nor revoked and whose role is
// not viewer. The caller holds the lock.
func (s *Store) seatsUsed(orgID string) int {
	n := 0
	for _, m := range s.members {
		if m.OrgID == orgID && m.Role != RoleViewer {
			n++
		}
	}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.Role != RoleViewer && inv.AcceptedAt == nil && inv.RevokedAt == nil {
			n++
		}
	}
	return n
}

// requireSeat returns a SeatLimitError when the organization has no free seat for one more. The caller holds the lock.
func (s *Store) requireSeat(orgID string) error {
	o, ok := s.orgs[orgID]
	if !ok {
		return ErrNotFound
	}
	limit := o.Plan.SeatLimit()
	used := s.seatsUsed(orgID)
	if limit != UnlimitedSeats && used >= limit {
		return &SeatLimitError{Limit: limit, Used: used}
	}
	return nil
}

