// orgView is an organization with its seats. Seats.Limit is null when the plan has no limit.
type orgView struct {
	store.Org
	Seats seatsView `json:"seats"`
}

type seatsView struct {
	Used  int  `json:"used"`
	Limit *int `json:"limit"`
}

func (s *Server) viewOrg(o store.Org) orgView {
	st, _ := s.store.Seats(o.ID)
	v := orgView{Org: o, Seats: seatsView{Used: st.Used}}
	if st.Limit != store.UnlimitedSeats {
		limit := st.Limit
		v.Seats.Limit = &limit
	}
	return v
}

// seatError answers that a change needs a seat the organization does not have, or would leave it over its seat limit.
func seatError(w http.ResponseWriter, status int, code string, e *store.SeatLimitError) {
	writeJSON(w, status, map[string]any{"error": code, "limit": e.Limit, "used": e.Used})
}

func (s *Server) getOrg(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	o, ok := s.store.Org(p.OrgID)
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such organization")
		return
	}
	writeJSON(w, http.StatusOK, s.viewOrg(o))
}

