package store

import (
	"errors"
	"sync"
	"testing"
)

func seatLimitErr(t *testing.T, err error, limit, used int) {
	t.Helper()
	var e *SeatLimitError
	if !errors.As(err, &e) || e.Limit != limit || e.Used != used {
		t.Fatalf("err = %v, want seat limit %d used %d", err, limit, used)
	}
}

func TestPlanSeatLimits(t *testing.T) {
	if OrgFree.SeatLimit() != 3 || OrgTeam.SeatLimit() != 10 || OrgBusiness.SeatLimit() != UnlimitedSeats {
		t.Fatalf("limits: free %d, team %d, business %d", OrgFree.SeatLimit(), OrgTeam.SeatLimit(), OrgBusiness.SeatLimit())
	}
}

func TestSeatsCountMembersAndPendingInvites(t *testing.T) {
	s := New()
	o := newOrg(t, s, "A")
	owner, _ := s.CreateUser("owner@a.example", "Owner", t0)
	_, _ = s.AddMember(o.ID, owner.ID, RoleOwner, t0)
	viewer, _ := s.CreateUser("viewer@a.example", "Viewer", t0)
	_, _ = s.AddMember(o.ID, viewer.ID, RoleViewer, t0)
	if got, _ := s.Seats(o.ID); got.Used != 1 || got.Limit != 10 {
		t.Fatalf("seats = %+v", got)
	}

	inv, err := s.CreateInvite(o.ID, "new@a.example", RoleMember, owner.ID, t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateInvite(o.ID, "watch@a.example", RoleViewer, owner.ID, t0); err != nil {
		t.Fatalf("viewer invite: %v", err)
	}
	if got, _ := s.Seats(o.ID); got.Used != 2 {
		t.Fatalf("seats with a pending invite = %+v", got)
	}

	if _, _, _, err := s.AcceptInvite(inv.Token, "New", t0); err != nil {
		t.Fatal(err)
	}
	if got, _ := s.Seats(o.ID); got.Used != 2 {
		t.Fatalf("seats after accepting = %+v, want the same seat", got)
	}

	if _, err := s.SetMemberRole(o.ID, viewer.ID, RoleAdmin); err != nil {
		t.Fatal(err)
	}
	if got, _ := s.Seats(o.ID); got.Used != 3 {
		t.Fatalf("seats after a viewer becomes admin = %+v", got)
	}
	if _, err := s.Seats("org_nope"); !errors.Is(err, nil) && err != nil {
		t.Fatal(err)
	}
}

func TestSeatLimitOnInvitesAndRoles(t *testing.T) {
	s := New()
	o := newOrg(t, s, "A")
	if _, err := s.UpdateOrg(o.ID, func(o *Org) error { o.Plan = OrgFree; return nil }); err != nil {
		t.Fatal(err)
	}
	owner, _ := s.CreateUser("owner@a.example", "Owner", t0)
	_, _ = s.AddMember(o.ID, owner.ID, RoleOwner, t0)

	inv, err := s.CreateInvite(o.ID, "m@a.example", RoleMember, owner.ID, t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateInvite(o.ID, "a@a.example", RoleAdmin, owner.ID, t0); err != nil {
		t.Fatal(err) // third seat
	}
	if _, err := s.CreateInvite(o.ID, "b@a.example", RoleBilling, owner.ID, t0); err == nil {
		t.Fatal("a fourth seat was granted")
	} else {
		seatLimitErr(t, err, 3, 3)
	}
	if _, err := s.CreateInvite(o.ID, "v@a.example", RoleViewer, owner.ID, t0); err != nil {
		t.Fatalf("viewers are free: %v", err)
	}

	// Accepting an invite never needs a seat: the invite already holds one.
	if _, _, _, err := s.AcceptInvite(inv.Token, "M", t0); err != nil {
		t.Fatalf("accept at the limit: %v", err)
	}

	// A revoked invite gives its seat back.
	var pending Invite
	for _, i := range s.Invites(o.ID) {
		if i.Role == RoleAdmin {
			pending = i
		}
	}
	if _, err := s.RevokeInvite(o.ID, pending.ID, t0); err != nil {
		t.Fatal(err)
	}
	viewer, _ := s.CreateUser("v2@a.example", "V", t0)
	_, _ = s.AddMember(o.ID, viewer.ID, RoleViewer, t0)
	if _, err := s.SetMemberRole(o.ID, viewer.ID, RoleMember); err != nil {
		t.Fatalf("a viewer gets the freed seat: %v", err)
	}
	if got, _ := s.Seats(o.ID); got.Used != 3 {
		t.Fatalf("seats = %+v", got)
	}
	viewer2, _ := s.CreateUser("v3@a.example", "V3", t0)
	_, _ = s.AddMember(o.ID, viewer2.ID, RoleViewer, t0)
	_, err = s.SetMemberRole(o.ID, viewer2.ID, RoleMember)
	seatLimitErr(t, err, 3, 3)
	if m, _ := s.Member(o.ID, viewer2.ID); m.Role != RoleViewer {
		t.Fatalf("a refused change still changed the role to %s", m.Role)
	}

	// Moving a seated member to another paid role changes nothing about seats.
	if _, err := s.SetMemberRole(o.ID, viewer.ID, RoleAdmin); err != nil {
		t.Fatalf("member to admin at the limit: %v", err)
	}
}

func TestSeatLimitOnPlanDowngrade(t *testing.T) {
	s := New()
	o := newOrg(t, s, "A")
	for _, email := range []string{"a@a.example", "b@a.example", "c@a.example", "d@a.example"} {
		u, _ := s.CreateUser(email, "U", t0)
		_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	}
	_, err := s.UpdateOrg(o.ID, func(o *Org) error { o.Plan = OrgFree; o.TimeZone = "Europe/Paris"; return nil })
	seatLimitErr(t, err, 3, 4)
	if got, _ := s.Org(o.ID); got.Plan != OrgTeam || got.TimeZone != "UTC" {
		t.Fatalf("a refused change changed the org: %+v", got)
	}
	if _, err := s.UpdateOrg(o.ID, func(o *Org) error { o.Plan = OrgBusiness; return nil }); err != nil {
		t.Fatalf("upgrade: %v", err)
	}
	if _, err := s.UpdateOrg(o.ID, func(o *Org) error { o.Plan = OrgFree; return nil }); err != nil {
		seatLimitErr(t, err, 3, 4)
	} else {
		t.Fatal("business to free with four seats was allowed")
	}
}

func TestSeatLimitHoldsUnderConcurrency(t *testing.T) {
	s := New()
	o := newOrg(t, s, "A")
	if _, err := s.UpdateOrg(o.ID, func(o *Org) error { o.Plan = OrgFree; return nil }); err != nil {
		t.Fatal(err)
	}
	owner, _ := s.CreateUser("owner@a.example", "Owner", t0)
	_, _ = s.AddMember(o.ID, owner.ID, RoleOwner, t0)
	if _, err := s.CreateInvite(o.ID, "one@a.example", RoleMember, owner.ID, t0); err != nil {
		t.Fatal(err)
	}
	// Two seats are used and one is left.

	const n = 8
	errs := make([]error, n)
	var wg sync.WaitGroup
	for i := range n {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, errs[i] = s.CreateInvite(o.ID, "x"+string(rune('a'+i))+"@a.example", RoleMember, owner.ID, t0)
		}()
	}
	wg.Wait()
	succeeded := 0
	for _, err := range errs {
		if err == nil {
			succeeded++
		} else {
			seatLimitErr(t, err, 3, 3)
		}
	}
	if succeeded != 1 {
		t.Fatalf("%d of %d invites succeeded with one seat left, want 1", succeeded, n)
	}
}

