	if got.Seats.Used != 1 || got.Seats.Limit == nil || *got.Seats.Limit != 3 {
		t.Fatalf("seats = %+v", got.Seats)
	}

	e.MustDo(http.StatusCreated, "POST", "/v1/invites", org.Key, map[string]string{"email": "a@freeco.example", "role": "member"}, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", org.Key, map[string]string{"email": "b@freeco.example", "role": "admin"}, nil)
	want := map[string]any{"error": "seat_limit_reached", "limit": float64(3), "used": float64(3)}
	r := e.Do("POST", "/v1/invites", org.Key, map[string]string{"email": "c@freeco.example", "role": "billing"})
	if r.Code != http.StatusPaymentRequired || !reflect.DeepEqual(r.Map(t), want) {
		t.Fatalf("invite at the limit: %s", r)
