	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+u.ID, org.Key, map[string]string{"role": "viewer"}, nil)
}

func TestSeatLimitOnPlanChange(t *testing.T) {
	e := apitest.New(t)
	org := e.NewOrg("Teamco", store.OrgTeam, "UTC")
	for i := range 3 {
		e.AddMember(org, fmt.Sprintf("m%d@teamco.example", i), store.RoleMember)
	}

	r := e.Do("PATCH", "/v1/org", org.Key, map[string]any{"plan": "free", "time_zone": "Asia/Tokyo"})
	want := map[string]any{"error": "over_seat_limit", "limit": float64(3), "used": float64(4)}
	if r.Code != http.StatusConflict || !reflect.DeepEqual(r.Map(t), want) {
		t.Fatalf("downgrade over the limit: %s", r)
	}
	var o struct {
		Plan     string `json:"plan"`
		TimeZone string `json:"time_zone"`
		Seats    struct {
			Used  int  `json:"used"`
			Limit *int `json:"limit"`
		} `json:"seats"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", org.Key, nil, &o)
	if o.Plan != "team" || o.TimeZone != "UTC" || o.Seats.Used != 4 || o.Seats.Limit == nil || *o.Seats.Limit != 10 {
		t.Fatalf("a refused change changed the org: %+v", o)
	}

	e.MustDo(http.StatusOK, "PATCH", "/v1/org", org.Key, map[string]any{"plan": "business"}, &o)
	if o.Seats.Limit != nil {
		t.Fatalf("business seats limit = %d, want null", *o.Seats.Limit)
	}
}

