		} `json:"seats"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", e.Globex.Key, nil, &o)
	if o.Seats.Used != 1 || o.Seats.Limit != nil {
		t.Fatalf("globex seats = %+v", o.Seats)
	}
}

func TestSeatLimitHoldsUnderConcurrentInvites(t *testing.T) {
	e := apitest.New(t)
	org := e.NewOrg("Racer", store.OrgFree, "UTC")
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", org.Key, map[string]string{"email": "first@racer.example", "role": "member"}, nil)

	const n = 5
	codes := make([]int, n)
	var wg sync.WaitGroup
	for i := range n {
		wg.Add(1)
		go func() {
			defer wg.Done()
			codes[i] = e.Do("POST", "/v1/invites", org.Key, map[string]string{"email": fmt.Sprintf("p%d@racer.example", i), "role": "member"}).Code
		}()
	}
	wg.Wait()
	created := 0
	for _, c := range codes {
		switch c {
		case http.StatusCreated:
			created++
		case http.StatusPaymentRequired:
		default:
			t.Fatalf("status %d", c)
		}
	}
	if created != 1 {
		t.Fatalf("%d of %d invites were created with one seat left, want 1", created, n)
	}
}

