376	// ---- invites
377	
378	// CreateInvite invites an email address to join an organization with a role. An invite for a role other than viewer holds
379	// a seat, so it needs a free one.
380	func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
381		email = strings.TrimSpace(email)
382		if !validEmail(email) {
383			return Invite{}, invalid("an invite needs a valid email address")
384		}
385		if !role.Valid() || role == RoleOwner {
386			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
387		}
388		s.mu.Lock()
389		defer s.mu.Unlock()
390		if _, ok := s.orgs[orgID]; !ok {
391			return Invite{}, ErrNotFound
392		}
393		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
394			if _, member := s.members[memberKey{orgID, uid}]; member {
395				return Invite{}, ErrAlreadyMember
396			}
397		}
398		if role != RoleViewer {
399			if err := s.requireSeat(orgID); err != nil {
400				return Invite{}, err
401			}
402		}
403		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: NewToken("invite_"), InvitedBy: invitedBy, CreatedAt: now.UTC()}
404		s.invites[inv.ID] = inv
405		return inv, nil
406	}
407	
408	// Invite returns one of an organization's invites.
409	func (s *Store) Invite(orgID, id string) (Invite, bool) {
410		s.mu.Lock()
411		defer s.mu.Unlock()
412		inv, ok := s.invites[id]
413		if !ok || inv.OrgID != orgID {
414			return Invite{}, false
415		}
416		return inv, true
417	}
418	
419	// Invites returns an organization's invites that were neither accepted nor revoked, oldest first.
420	func (s *Store) Invites(orgID string) []Invite {
421		s.mu.Lock()
422		defer s.mu.Unlock()
423		out := []Invite{}
424		for _, inv := range s.invites {
425			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
426				out = append(out, inv)
427			}
428		}
429		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
430		return out
431	}
432	
433	// RevokeInvite withdraws an invite.
434	func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
435		s.mu.Lock()
436		defer s.mu.Unlock()
437		inv, ok := s.invites[id]
438		if !ok || inv.OrgID != orgID {
439			return Invite{}, ErrNotFound
440		}
441		if inv.RevokedAt == nil {
442			t := now.UTC()
443			inv.RevokedAt = &t
444			s.invites[id] = inv
445		}
446		return inv, nil
447	}
