451	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
452		s.mu.Lock()
453		defer s.mu.Unlock()
454		var inv Invite
455		found := false
456		for _, i := range s.invites {
457			if i.Token == token && token != "" {
458				inv, found = i, true
459				break
460			}
461		}
462		if !found || inv.RevokedAt != nil {
463			return User{}, Member{}, APIKey{}, ErrNotFound
464		}
465		var u User
466		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
467			u = s.users[id]
468		} else {
469			name = strings.TrimSpace(name)
470			if name == "" {
471				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
472			}
473			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
474			s.users[u.ID] = u
475			s.usersByEmail[normEmail(u.Email)] = u.ID

