378	// CreateInvite invites an email address to join an organization with a role. An invite for a role other than viewer holds
379	// a seat, so it needs a free one.
380	func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
381		email = strings.TrimSpace(email)
382		if !validEmail(email) {
383			return Invite{}, invalid("an invite needs a valid email address")
384		}
385		if !role.Valid() || role == RoleOwner {
386			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
387		}
388		s.mu.Lock()
389		defer s.mu.Unlock()
390		if _, ok := s.orgs[orgID]; !ok {
391			return Invite{}, ErrNotFound
392		}
393		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
394			if _, member := s.members[memberKey{orgID, uid}]; member {
395				return Invite{}, ErrAlreadyMember
396			}
397		}
398		if role != RoleViewer {
399			if err := s.requireSeat(orgID); err != nil {
400				return Invite{}, err
401			}
402		}
403		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: NewToken("invite_"), InvitedBy: invitedBy, CreatedAt: now.UTC()}
404		s.invites[inv.ID] = inv
405		return inv, nil
406	}
