419	// Invites returns an organization's invites that were neither accepted nor revoked, oldest first.
420	func (s *Store) Invites(orgID string) []Invite {
421		s.mu.Lock()
422		defer s.mu.Unlock()
423		out := []Invite{}
424		for _, inv := range s.invites {
425			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
426				out = append(out, inv)
427			}
428		}
429		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
430		return out
431	}
