433	// RevokeInvite withdraws an invite.
434	func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
435		s.mu.Lock()
436		defer s.mu.Unlock()
437		inv, ok := s.invites[id]
438		if !ok || inv.OrgID != orgID {
439			return Invite{}, ErrNotFound
440		}
